```go
package main

import (
    "fmt"
    "strings"
)

func main() {
    fmt.Printf("%q\n", strings.Fields("  Go\tweb\nAPI  "))
    fmt.Printf("%q\n", strings.Split("a,,c", ","))
}
```
Fields returns `["Go" "web" "API"]`; Split returns `["a" "" "c"]`.

```go
package main

import (
    "fmt"
    "strings"
)

func addLabel(builder *strings.Builder, label string) {
    if builder.Len() > 0 {
        builder.WriteString(" | ")
    }
    builder.WriteString(label)
}

func main() {
    var builder strings.Builder
    builder.Grow(20)
    addLabel(&builder, "Go")
    addLabel(&builder, "API")
    fmt.Println(builder.String())
}
```
The output is `Go | API`. The helper receives a pointer instead of copying the non-zero Builder.
